#!/usr/bin/env python3
"""timeline.json -> scenes/timeline.js, scenes/registry.js, index.html (audio track per scene), placeholder scene files."""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
tl = json.load(open(f"{ROOT}/build/timeline.json"))
total = tl["total"]

open(f"{ROOT}/scenes/timeline.js", "w").write("// generated by build/assemble.py — do not edit\nexport default " + json.dumps(tl, ensure_ascii=False) + ";\n")
ids = [s["id"] for s in tl["scenes"]]
open(f"{ROOT}/scenes/registry.js", "w").write(
    "// generated by build/assemble.py — do not edit\n" + "".join(f'import {i} from "./{i}.js";\n' for i in ids) + f"export default [{', '.join(ids)}];\n")

PLACEHOLDER = '''// placeholder — replace with the real scene
export default {
  id: "%s", eyebrow: "", headline: "",
  build({ kit, group, camera }) {
    kit.desk(group);
    return { render(t) { kit.setIso(camera, kit.P(0, 1, 0), 5); } };
  },
};
'''
for i in ids:
    p = f"{ROOT}/scenes/{i}.js"
    if not os.path.exists(p): open(p, "w").write(PLACEHOLDER % i)

audio = "\n".join(
    f'  <audio id="vo-{s["id"]}" src="assets/audio/{s["id"]}.mp3" data-start="{s["start"] + tl["lead"]:.2f}" data-duration="{s["audioDur"]:.2f}" data-volume="1"></audio>'
    for s in tl["scenes"])

html = f'''<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=1920, height=1080" />
<title>Granola 是怎么做出来的</title>
<link rel="stylesheet" href="scenes/style.css" />
</head>
<body>
<div id="root" data-composition-id="main" data-start="0" data-width="1920" data-height="1080" data-duration="{total:.2f}" data-no-timeline>
{audio}
  <canvas id="three-layer" class="clip" data-start="0" data-duration="{total:.2f}" data-track-index="1"></canvas>
  <div id="overlay" class="stage clip" data-start="0" data-duration="{total:.2f}" data-track-index="2">
    <div id="scene-overlays"></div>
    <div class="title" id="title"><div class="eyebrow" id="eyebrow"></div><div class="headline" id="headline"></div></div>
    <div class="cap-wrap"><div class="cap" id="cap"></div></div>
    <div id="fade"></div>
  </div>
</div>
<script type="importmap">
  {{ "imports": {{
    "three": "https://cdn.jsdelivr.net/npm/three@0.181.2/build/three.module.js",
    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.181.2/examples/jsm/"
  }} }}
</script>
<script type="module" src="scenes/main.js"></script>
</body>
</html>
'''
open(f"{ROOT}/index.html", "w").write(html)
print("assembled", len(ids), "scenes,", total, "s")
